"""
Templates for coverage system components
"""

COVERAGE_TRACKER_TEMPLATE = '''# Auto-generated by GDSentry Coverage System
# DO NOT EDIT - This file is temporary and will be deleted

extends Node

# Signal emitted when coverage data is written
signal coverage_written(path: String, success: bool)

# Coverage data: { "file.gd": { line_num: hit_count } }
var _coverage_data: Dictionary = {}

# Configuration
var _output_path: String = ""
var _enabled: bool = true

func _ready() -> void:
\t# Read configuration from environment
\t_output_path = OS.get_environment("GDSENTRY_COVERAGE_OUTPUT")
\tif _output_path.is_empty():
\t\t_output_path = ".gdsentry/coverage/"
\t
\t_enabled = OS.get_environment("GDSENTRY_COVERAGE") == "1"
\t
\tif _enabled:
\t\tprint("[Coverage] Tracker initialized: %s" % _output_path)


func hit(file_path: String, line_num: int) -> void:
\t"""Record a line hit during execution"""
\tif not _enabled:
\t\treturn
\t
\tif not _coverage_data.has(file_path):
\t\t_coverage_data[file_path] = {}
\t
\tif not _coverage_data[file_path].has(line_num):
\t\t_coverage_data[file_path][line_num] = 0
\t
\t_coverage_data[file_path][line_num] += 1


func reset() -> void:
\t"""Clear all coverage data"""
\t_coverage_data.clear()


func get_stats() -> Dictionary:
\t"""Get current coverage statistics (for debugging)"""
\tvar files_tracked = _coverage_data.size()
\tvar total_hits = 0
\t
\tfor file_data in _coverage_data.values():
\t\tfor hit_count in file_data.values():
\t\t\ttotal_hits += hit_count
\t
\treturn {
\t\t"files_tracked": files_tracked,
\t\t"total_hits": total_hits,
\t\t"data_size_bytes": JSON.stringify(_coverage_data).length()
\t}


func write_coverage_data(path: String = "") -> bool:
\t"""Write accumulated coverage data to JSON file"""
\tif path.is_empty():
\t\tpath = _output_path + "coverage_data.json"
\t
\tvar data = {
\t\t"format_version": "1.0",
\t\t"timestamp": Time.get_datetime_string_from_system(),
\t\t"files": _coverage_data
\t}
\t
\tvar file = FileAccess.open(path, FileAccess.WRITE)
\tif file == null:
\t\tvar error_msg = "Cannot write coverage data: " + error_string(FileAccess.get_open_error())
\t\tpush_error(error_msg)
\t\t_write_error_file("coverage_error.txt", "Failed to write coverage data: " + error_string(FileAccess.get_open_error()))
\t\tcoverage_written.emit(path, false)
\t\treturn false
\t
\tfile.store_string(JSON.stringify(data, "\\t"))
\tfile.close()
\t
\tprint("[Coverage] Data written: %s" % path)
\tcoverage_written.emit(path, true)
\treturn true


func _write_error_file(filename: String, message: String) -> void:
\t"""Write error message to file for Python to read"""
\tvar error_path = _output_path + filename
\tvar file = FileAccess.open(error_path, FileAccess.WRITE)
\tif file:
\t\tfile.store_string(message)
\t\tfile.close()


func _notification(what: int) -> void:
\t"""Ensure coverage data is written even if tests crash"""
\tif what == NOTIFICATION_WM_CLOSE_REQUEST:
\t\tif _enabled and not _coverage_data.is_empty():
\t\t\twrite_coverage_data()
'''
